INSERT INTO events (dynasty_id, year, year_end, lng, lat, short, title, detail, impact, place, category) VALUES
  ('song', 1129, 1130, 121.84, 29.88, '搜山检海', '搜山检海 · 高宗浮海避金', '金将完颜宗弼率军渡江南下，分兵追踪高宗行在，扬言搜山检海捉赵构。高宗自临安经越州退至明州，登船浮海避敌，漂泊温州沿海数月，两浙州县惨遭蹂躏。', '宋室浮海得全，然两浙膏腴之地惨遭兵燹，户口流散，朝廷自此绝口不提还都中原，偏安格局遂成定局。', '明州（今浙江宁波）', 'military'),
  ('song', 1129, 1129, 120.16, 30.25, '苗刘兵变', '苗刘兵变 · 明受之变', '卫戍将领苗傅、刘正彦愤于宦官妄赏、诸将无功而擢，在杭州发动兵变，逼高宗退位，立三岁幼子，改元明受，孟太后垂帘听政。韩世忠、张俊等起兵勤王，高宗复位，苗刘伏诛。', '变起旬月即平，然高宗视武将拥兵为心腹之患，对诸将猜忌骤深，为日后收兵柄与岳飞之狱埋下伏笔。', '临安（今浙江杭州）', 'era'),
  ('song', 1130, 1130, 118.90, 32.09, '黄天荡之战', '黄天荡之战 · 韩世忠扼江', '金军北撤，韩世忠以八千水师扼守镇江江面，围完颜宗弼十万之众于黄天荡，梁红玉亲执桴鼓助战，相持四十余日，金军凿老鹳河故道一夜遁去。', '寡军困劲敌数十日，江南民心大振，宋军江防水战之长尽显，金军此后多年不敢轻议渡江。', '黄天荡（今江苏南京东北）', 'military'),
  ('song', 1130, 1135, 111.69, 29.03, '钟相杨幺起义', '钟相杨幺起义 · 洞庭湖大起义', '鼎州武陵人钟相结社聚众，倡等贵贱、均贫苦之号，湖湘贫民翕然从之。建炎四年举兵建号楚，钟相败死后杨幺继领其众，据洞庭水寨陆耕水战，官军屡讨无功，绍兴五年岳飞以招讨兼施平之。', '大起义暴露南宋赋敛苛急与兼并之弊，宋廷平乱后蠲减湖湘租赋以安流亡，然内忧外患交乘，国力大耗。', '鼎州（今湖南常德）', 'economy'),
  ('song', 1131, 1131, 107.10, 34.33, '和尚原之战', '和尚原之战 · 吴玠保蜀', '金将完颜宗弼会诸道兵数万，自宝鸡结连珠营来攻，吴玠、吴璘兄弟以散卒数千据和尚原之险，强弓迭射，矢如雨下，宗弼身中流矢，金军大溃，蜀口转安。', '富平新败之后宋军首获大捷，秦岭防线重立，四川免遭金人铁骑蹂躏，吴氏兄弟自此世守蜀口。', '和尚原（今陕西宝鸡西南）', 'military'),
  ('song', 1131, 1145, 119.02, 33.61, '淮南屯田', '淮南屯田 · 营田实边', '两淮屡经兵燹，丁壮流亡，沃壤弥望皆荒。朝廷设官经理营田，募民佃种，军队且耕且守，蠲其赋役以劝来者，淮南垦务渐次恢复，江淮军储稍纾。', '边郡经济缓慢复苏，就地供军减少江浙转饷之困，实边固防，为宋金对峙下的两淮防线提供物质支撑。', '楚州（今江苏淮安）', 'economy'),
  ('song', 1132, 1132, 113.70, 31.26, '陈规火枪', '陈规火枪 · 世界最早管形火器', '德安知府陈规御李横军攻城，以火炮药制成长竹杆火枪二十余条，募枪手持之焚敌天桥，喷焰烧其攻具，是管形火器见于世界记载之最早者。', '火器由抛掷燃烧迈向管身喷射的关键一步，开管形火器之先河，后世突火枪、金属火铳皆由此嬗变。', '德安（今湖北安陆）', 'invention'),
  ('song', 1132, 1140, 120.16, 30.25, '李清照南渡', '李清照南渡 · 易安词风之变', '靖康之难，李清照与赵明诚青州故第十余屋书册金石尽毁于兵火。南渡后明诚病殁，她孤身携残卷流转江浙，晚年寓杭州、金华，词风由清丽转为沉郁凄怆。', '声声慢、金石录后序等绝唱以一身之哀写家国之痛，将婉约词推至极境，为南渡士人心史之第一见证。', '临安（今浙江杭州）', 'figure'),
  ('song', 1134, 1134, 112.12, 32.01, '收复襄汉', '收复襄汉 · 岳飞复六郡', '岳飞由鄂州出师北伐伪齐，先复郢州、随州，再下襄阳，并克唐州、邓州、信阳军，襄汉六郡尽归版图，为南宋立国以来首次大规模规复失地。', '汉水门户重归宋有，长江中游防务立定，岳家军自此以荆襄为基，屯田练兵，隐然有饮马中原之势。', '襄阳（今湖北襄阳）', 'military'),
  ('song', 1137, 1137, 117.28, 31.86, '淮西军变', '淮西军变 · 郦琼叛降伪齐', '张浚罢刘光世兵柄，以枢密都承旨吕祉往庐州节制淮西军，处置失宜，将士汹汹。绍兴七年八月，副都统制郦琼煽众，杀吕祉，率兵四万余、裹百姓数万叛降伪齐。', '淮西主力一夕瓦解，江防门户洞开，张浚引咎罢相，主战阵营再挫，朝廷自此愈倾于对金驯服求和。', '庐州（今安徽合肥）', 'era'),
  ('song', 1138, 1155, 120.16, 30.25, '秦桧独相', '秦桧独相 · 和议体制确立', '秦桧绍兴八年再相，力赞和议，倾轧赵鼎、张浚诸贤，门客亲党布列台谏，凡异己者必逐之。此后独相十七年，晚年兴文字之狱，天下籍口，岳飞父子之狱亦成于其手。', '相权之重为宋所未有，主战之声尽息于朝，南宋偏安国是与钳制舆论之局，皆由此铸定，流毒数十年。', '临安（今浙江杭州）', 'era'),
  ('song', 1140, 1140, 115.81, 32.90, '顺昌大捷', '顺昌大捷 · 刘锜守城', '新任东京副留守刘锜率师万八千抵顺昌，金军主力旋至围城。锜凿沉舟楫示无还心，以逸待劳，婴城力战，大破铁浮图、拐子马，完颜宗弼败走。', '以不足两万之众挫金军精锐于城下，时人始信金兵可破，中原人心激动，为岳飞北伐张本。', '顺昌（今安徽阜阳）', 'military'),
  ('song', 1140, 1140, 114.02, 33.58, '郾城大捷', '郾城大捷 · 岳飞破拐子马', '金军扑郾城，岳飞以背嵬军与游奕军迎击，命步卒持麻扎刀、提刀入阵，勿仰视，专剁马足，拐子马一排俱仆。鏖战数十合，金军大败，颍昌复大捷，兵锋直逼东京。', '野战正面摧折金军最精锐之骑军，河北忠义民兵蜂起响应，惜班师诏下，十年之力废于一旦。', '郾城（今河南漯河）', 'military'),
  ('song', 1150, 1162, 118.58, 24.93, '市舶鼎盛', '市舶鼎盛 · 刺桐港崛起', '宋金休兵，海道大通，广州、泉州、明州三司并盛，蕃舶岁至，香药犀象充牣库藏。绍兴末市舶岁入约二百万缗，远过北宋，泉州号曰刺桐，名闻南海诸国。', '舶税成为南宋财政大宗，东南造船、丝瓷诸业并荣，海上丝路臻于极盛，泉州南外宗正司与回商聚落由是渐成。', '泉州（今福建泉州）', 'economy'),
  ('song', 1153, 1154, 120.16, 30.25, '陆游除名', '锁厅试风波 · 陆游除名', '陆游赴临安应两浙转运司锁厅试，文辞冠于多士，擢第一，而秦桧孙秦埙居其下。桧怒，主司黜落陆游。秦桧死，方以荫补登仕，其主恢复之论终身为时所忌。', '才士折于权门，科场蹭蹬反砥砺其诗，陆游终身以恢复为念，屡摈不改，诗名与志节相成。', '临安（今浙江杭州）', 'figure'),
  ('song', 1161, 1161, 118.50, 31.70, '采石之战', '采石大捷 · 虞允文却敌', '完颜亮举国南牧，亲执小红旗督军渡江，采石宋军无主，中书舍人虞允文犒师督战，以海鳅船冲敌，霹雳炮震之，金舟尽没。亮转趋扬州，为部下所杀。', '书生奋起，于顷刻间却号称六十万之众，江防转危为安，南宋再度免于覆亡，主战士气因之大振。', '采石（今安徽马鞍山）', 'military'),
  ('song', 1163, 1163, 116.96, 33.65, '符离之败', '符离之败 · 隆兴北伐受挫', '孝宗锐意恢复，张浚督李显忠、邵宏渊北伐，渡淮取宿州，中原震动。二将不相下，宏渊按兵不动，金军大至，符离一夕溃败，丧师资械殆尽，北伐遂罢。', '隆兴北伐功亏一篑，主战派张浚罢去，宋金重开和议，岁币虽减而屈己之名犹在，恢复之志再挫。', '符离（今安徽宿州）', 'military'),
  ('song', 1165, 1175, 118.49, 33.01, '榷场重开', '榷场重开 · 隆兴和后互市', '隆兴和议既成，宋金罢兵，复开盱眙、光州、安丰军、枣阳诸榷场，以茶、绢、香药易北地羊马皮货，课税有则，商旅络绎，聘使往来渐复旧章。', '互市之利与和平红利并至，边郡苏醒，商旅渐通，国计稍宽，为乾淳之治的安定繁荣供给外部条件。', '盱眙（今江苏盱眙）', 'economy'),
  ('song', 1170, 1170, 116.40, 39.90, '范成大使金', '范成大使金 · 揽辔中原', '范成大奉命使金，面请迁河南陵寝之地，实求更定受书之仪。金君臣愕怒，胁迫万端，成大不为屈，全节而归。途中览中原故墟，赋纪行诗七十二首，并撰揽辔录。', '使金诗写尽故都遗黎之痛，与揽辔录并为传世名篇，气节文章为朝野推重，遂称中兴使臣之冠。', '中都（今北京）', 'figure'),
  ('song', 1172, 1172, 107.02, 33.07, '南郑从军', '陆游南郑从军 · 铁马秋风', '陆游入四川宣抚使王炎幕府，干办公事于南郑，亲至大散关、骆谷口察看形势，陈经略中原之策于幕府。从戎八月而幕散，铁马秋风大散关遂成其终身意象。', '八月军中岁月使其诗风自工丽转苍茫豪宕，书愤、示儿诸名篇的悲壮根柢，皆植于此段从戎经历。', '南郑（今陕西汉中）', 'figure'),
  ('song', 1182, 1192, 117.94, 28.45, '带湖闲居', '辛弃疾带湖闲居 · 稼轩词成', '辛弃疾遭劾落职，退居上饶带湖，葺新居自号稼轩，凡十年湖山投闲。胸中九转之郁尽泄于长短句，破阵子醉里挑灯看剑诸阕，皆此期所作。', '闲居反成就稼轩词之高峰，悲壮沉雄，别开一面，后世遂以苏辛并称，为南宋爱国词之宗。', '上饶（今江西上饶）', 'figure'),
  ('song', 1190, 1192, 117.65, 24.51, '漳州经界', '朱熹漳州经界', '朱熹知漳州，奏行经界法，欲正经界、均赋税，核实田亩以杜隐冒。豪家猾吏沮之，漕臣异议，朝廷延宕不行。熹力求去任，其在漳奏置社仓诸政，漳人称之。', '经界之沮尽现南宋土地兼并与赋役不均之积弊，而社仓等惠政则行于七闽，为后世荒政所师法。', '漳州（今福建漳州）', 'figure'),
  ('song', 1194, 1194, 120.16, 30.25, '绍熙内禅', '绍熙内禅 · 宁宗即位', '光宗因疾久不视朝，孝宗崩而不能执丧，人情汹汹。赵汝愚、韩侂胄等白宪圣太后，奉命禅位于皇子嘉王赵扩，是为宁宗，朝局危而复安。', '帝位危机和平化解，然赵、韩以定策相争，韩侂胄结党擅政，党禁与权相迭起之局由此而开。', '临安（今浙江杭州）', 'era'),
  ('song', 1195, 1200, 120.16, 30.25, '庆元党禁', '庆元党禁 · 伪学之禁', '韩侂胄逐赵汝愚，斥道学为伪学，立伪学逆党籍，朱熹、周必大等五十九人挂名其间，禁锢其门人仕进。历时六年，至韩侂胄谋北伐，方弛其禁以收人心。', '以学争为政争，士类横被清洗，道学声誉反而愈高，党禁既解，理学终据南宋后期官学之席。', '临安（今浙江杭州）', 'era'),
  ('song', 1207, 1233, 120.16, 30.25, '史弥远专权', '史弥远专权 · 矫诏立理宗', '开禧败后，史弥远与杨皇后合谋，矫诏诛韩侂胄于玉津园，函首送金乞和。后宁宗崩，又擅废皇子济王竑，立宗室昀为理宗，独相二十余年，威福自专。', '权相之祸至此极矣，废立出于私门，台谏噤声，货币、边防诸政并坏，南宋之衰实基于此。', '临安（今浙江杭州）', 'era'),
  ('song', 1210, 1220, 119.42, 32.39, '铁钱会子', '两淮铁钱会子 · 币制分界', '宋金交兵，铜钱外流日甚，朝廷因之专用铁钱于两淮，并造铁钱会子，与东南铜钱会子分界而治。商旅越境必须兑换，折阅滋甚，淮上物价为之踊贵。', '币制分界意在御敌聚财，实成流通之梗，纸币信用随军费日蹙而愈坏，楮价日贱之弊自此不可反。', '扬州（今江苏扬州）', 'economy'),
  ('song', 1210, 1210, 120.58, 30.03, '放翁示儿', '放翁绝笔 · 示儿', '陆游卒于山阴故庐。绝笔示儿诗云：死去元知万事空，但悲不见九州同。王师北定中原日，家祭无忘告乃翁。念念恢复，至死不渝，闻者无不动容。', '一首绝笔凝尽南宋志士毕生之悲愿，八百年来传诵不衰，成为中华民族爱国诗篇至深沉之象征。', '山阴（今浙江绍兴）', 'figure'),
  ('song', 1217, 1224, 112.77, 32.14, '嘉定之战', '嘉定之战 · 宋金再战七年', '金受蒙古侵逼，欲取偿于宋，嘉定十年大举南攻，兵锋遍两淮、京湖、川陕。宋军婴城固守，枣阳、光州、大散关诸役屡挫金师，鏖战七年，各疲而罢。', '蒙古坐大之际宋金互耗，金北失于蒙、南困于宋，南宋亦军费山积、楮币大贬，双方俱创，卒同为蒙古所乘。', '枣阳（今湖北枣阳）', 'military'),
  ('song', 1223, 1223, 121.14, 28.87, '赤城志', '赤城志成书 · 台州郡志', '台州守延聘临海名儒陈耆卿纂修郡志，成书四十卷，凡地理、公廨、秩官、版籍、山水、人物诸门，记载详核，叶适为之序，学者推为宋志上品。', '为宋代方志成熟之表征，完整保存台郡田赋、物产、人物文献，后世修志多取法其体例，浙东文脉赖以可考。', '临海（今浙江临海）', 'figure'),
  ('song', 1236, 1236, 112.24, 30.33, '江陵之战', '江陵之战 · 孟珙却敌', '蒙古军袭破襄阳，长驱荆湖，枝江、监利告急，江陵震动。孟珙驰援，分布舰列、变易旌旗，军容相属，夜袭连破蒙古军寨二十有四，夺还被掳生民，江陵解严。', '遏蒙古首次深入长江中游之势，孟珙以是役崭然见头角，自此专当京湖一面，成为南宋后期国防之干城。', '江陵（今湖北荆州）', 'military'),
  ('song', 1243, 1253, 106.55, 29.56, '余玠守蜀', '余玠守蜀 · 山城防御体系', '余玠开府重庆，礼聘播州冉氏兄弟，徙合州城于钓鱼山，因山为垒，棋布星列，青居、大获、云顶、苦竹诸城相望，屯兵积粟，储以待敌，蜀防为之一新。', '山城体系支撑残蜀三十余年，蒙古铁骑困于崇山坚垒，钓鱼城他日击毙蒙哥大汗，全恃今日之规模。', '重庆府（今重庆）', 'military'),
  ('song', 1247, 1247, 112.94, 28.23, '洗冤集录', '宋慈洗冤集录 · 法医学开山', '宋慈屡任提点刑狱，博采内恕录诸书，益以亲验之功，淳祐七年撰成洗冤集录，自序云狱事莫重于大辟，大辟莫重于初情，初情莫重于检验。', '世界现存第一部系统法医学专著，历宋元明清检验奉为圭臬，朝鲜、日本诸译本行世，泽被七百年。', '长沙（今湖南长沙）', 'invention'),
  ('song', 1259, 1259, 114.32, 30.55, '鄂州之战', '鄂州之战 · 忽必烈北返', '蒙哥死于钓鱼山下，忽必烈议决渡江，围鄂州，城中死守。贾似道率师入援，会蒙古诸王谋立争位，忽必烈允和北返。似道归朝匿乞和之实，以大捷闻。', '南宋惊险渡过一劫，然和战失实，贾似道由此冒功擅政，后拒纳郝经，和款遂为蒙古再举之名。', '鄂州（今湖北武汉武昌）', 'military'),
  ('song', 1259, 1259, 116.79, 32.58, '突火枪', '突火枪 · 子窠初鸣', '寿春府军前创造突火枪，以巨竹为筒，内安子窠，药燃焰绝，子窠激射，声如炮震，闻于百五十余步之外。以竹发弹，射远贯坚，前此火器莫能及。', '管形射击火器至此成熟，元明金属铳枪相承而进，火药武器经征战与商路西传，卒改世界军史。', '寿春（今安徽寿县）', 'invention'),
  ('song', 1263, 1275, 120.16, 30.25, '公田法', '贾似道公田法 · 回买官田', '楮币日轻，军饷浩繁，贾似道行公田法于浙西，回买官户逾限之田为公田，租入赡兵。始限二百亩，继累减至百亩，抑价给会，吏缘为奸，浙右骚然。', '一时稍纾饷源楮币之急，然强买病农，富室怨咨，宋亡之际江南竟乏同仇之心，识者归咎于此。', '临安（今浙江杭州）', 'economy'),
  ('song', 1267, 1273, 112.12, 32.01, '襄樊之战', '襄樊之战 · 六年围城', '蒙古纳刘整之策，筑鹿门、白河口诸堡，练水军数万，困襄阳、樊城，断其粮援。宋屡发师援之皆败，张顺、张贵率死士三千犯重围入城，力战而没。城守六年，樊城先破，吕文焕以襄阳降。', '门户既失，元军因造战舰数千，顺汉水长驱而下，长江之险尽为彼有，南宋残局自此不可复支。', '襄阳（今湖北襄阳）', 'military'),
  ('song', 1275, 1275, 117.86, 30.92, '丁家洲之战', '丁家洲之溃 · 精锐尽丧', '元军东下，朝野汹惧，贾似道不得已率精兵十三万、战舰二千五百艘次丁家洲。夏贵先逸，孙虎臣继遁，诸军一夕皆溃，军资尽委，似道遁扬州。', '宋最后可战之兵一朝崩解，沿江州郡自是望风迎降，元军长驱直抵临安城下，宋祚存亡已在旦夕。', '丁家洲（今安徽铜陵东北）', 'military'),
  ('song', 1276, 1276, 120.16, 30.25, '临安陷落', '临安陷落 · 谢太后出降', '伯颜军至皋亭山，宋使两奉表乞和，皆不许。谢太后遂携五岁恭帝奉表出降，宋室在江南的统治实质已亡。益王、广王走温州入闽，兵事转徙东南。', '临安开府降元，江南诸城犹自苦守，残部奉二王转战闽广，抗元重心南移，进入最后三年。', '临安（今浙江杭州）', 'era'),
  ('song', 1276, 1276, 119.30, 26.08, '益王即位', '益王即位 · 福州行朝', '临安既陷，陈宜中、张世杰、陆秀夫奉益王昰、卫王昺至福州，奉昰即皇帝位，是为端宗，改元景炎，杨太后同听政，以福州府治为行宫，图续社稷于东南。', '危亡中续立朝廷，闽广义兵稍稍来集，然地促兵寡，元师追迫，行朝卒弃陆浮海，播越靡有定所。', '福州（今福建福州）', 'era')
